function drawScope(){const can=$('scopeGraph');if(!can)return;const g=can.getContext('2d'),w=can.width,h=can.height;g.fillStyle='#071a22';g.fillRect(0,0,w,h);g.strokeStyle='#1d4450';g.lineWidth=1;for(let x=0;x<w;x+=w/12){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke()}for(let y=0;y<h;y+=h/8){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke()}g.setLineDash([6,6]);g.strokeStyle='#4d7280';g.beginPath();g.moveTo(0,h*.7);g.lineTo(w,h*.7);g.stroke();g.setLineDash([]);let summaries=[];
 [[netA,'#57f2de'],[netB,'#f3c47b']].forEach(([net,color],j)=>{const out=C.waveform(B.getState(),net);summaries.push(`<div><i style="background:${color}"></i> ${esc(net)}: ${out.min.toFixed(3)}–${out.max.toFixed(3)} V<br><small>${esc(out.frequencyLabel)}</small></div>`);g.strokeStyle=color;g.lineWidth=2.5;g.beginPath();for(let i=0;i<out.values.length;i++){const x=i/(out.values.length-1)*w;const clip=Math.min(15,Math.max(-15,out.values[i]/scopeDiv));const y=h*(.79-.06*clip)+j*7;if(i===0)g.moveTo(x,y);else g.lineTo(x,y)}g.stroke()});g.fillStyle='#8db7be';g.font='13px monospace';g.fillText(`${scopeDiv.toFixed(1)} V/div  |  ${scopeTime}x time  |  ${scopePaused?'HOLD':'RUN'}  |  TRAINER`,15,26);$('scopeReadings').innerHTML=summaries.join('');}
function drawThermal(){const c=$('heatGraph');if(!c)return;const g=c.getContext('2d'),w=c.width,h=c.height;g.fillStyle='#122936';g.fillRect(0,0,w,h);g.fillStyle='#165249';g.fillRect(w*.06,h*.08,w*.88,h*.83);g.strokeStyle='#67a99b';g.lineWidth=4;g.strokeRect(w*.06,h*.08,w*.88,h*.83);const hot=C.thermal(B.getState());for(const p of hot){const x=p.x*w,y=p.y*h,r=Math.max(32,(p.c-24)*1.6);const gr=g.createRadialGradient(x,y,4,x,y,r);const power=Math.min(1,(p.c-24)/70);gr.addColorStop(0,thermoPalette==='blue'?`rgba(180,230,255,${.5+power*.5})`:`rgba(255,251,159,${.5+power*.5})`);gr.addColorStop(.35,thermoPalette==='blue'?'rgba(53,116,255,.46)':'rgba(255,105,60,.58)');gr.addColorStop(1,'rgba(17,55,64,0)');g.fillStyle=gr;g.fillRect(x-r,y-r,r*2,r*2);g.fillStyle='#e8ffff';g.font='bold 13px monospace';g.fillText(p.key+' '+Math.round(p.c)+'°',x-30,y-17)}$('hotspotList').innerHTML=hot.sort((a,b)=>b.c-a.c).slice(0,6).map(p=>`<div class="hot-row"><span>${p.key}</span><strong>${p.c.toFixed(1)} °C</strong></div>`).join('')}
